<script setup>
import { ref, watch } from 'vue';
import { api, action, downloadFile } from '../api';
import { useAuth } from '../stores/auth';
import { ElMessage, ElMessageBox } from 'element-plus';
const auth=useAuth(),nickname=ref(auth.user?.nickname||''),busy=ref(false),result=ref(null),upload=ref(null),memory=ref(''),memoryBusy=ref(false);
watch(()=>auth.user?.nickname,value=>{if(!nickname.value)nickname.value=value||'';});
async function loadMemory(){await action(async()=>{memory.value=await api('/api/assistant/memory');});}
async function saveMemory(){memoryBusy.value=true;await action(async()=>{await api('/api/assistant/memory',{method:'PUT',body:{preferences:memory.value}});ElMessage.success('Agent 偏好已保存');});memoryBusy.value=false;}
async function profile(){await action(async()=>{await api('/api/auth/profile',{method:'PUT',body:{nickname:nickname.value}});await auth.check();ElMessage.success('昵称已保存');});}
async function backup(){busy.value=true;await action(()=>downloadFile('/api/workspace/backup','book-agent-backup.zip'));busy.value=false;}
async function restore(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>100*1024*1024){ElMessage.error('备份文件不能超过 100MB');return;}try{await ElMessageBox.confirm('备份中的 Book 将作为新草稿恢复到你的空间，原有内容保留。','恢复知识库',{confirmButtonText:'恢复为新草稿',cancelButtonText:'取消'});}catch{return;}busy.value=true;await action(async()=>{const body=new FormData();body.append('file',file);result.value=await api('/api/workspace/restore',{method:'POST',body});ElMessage.success('备份已恢复，正在建立索引');});busy.value=false;}
loadMemory();
</script>
<template><section><div class="page-heading"><div><h1>空间设置与备份</h1><p>个人内容、版本与原文件由服务端保存。使用同一账号可在不同设备继续访问。</p></div></div><div class="knowledge-split settings-grid"><form class="knowledge-panel collection-form" @submit.prevent="profile"><h2>个人资料</h2><p class="muted">账号：{{auth.user?.username}} · {{auth.user?.role==='ADMIN'?'系统管理员':'个人知识空间'}}</p><label for="profile-nickname">昵称</label><el-input id="profile-nickname" v-model="nickname" maxlength="32" required/><el-button native-type="submit">保存昵称</el-button></form><form class="knowledge-panel collection-form" @submit.prevent="saveMemory"><h2>Agent 长期偏好</h2><p class="muted">只保存你主动填写的回答风格、解释水平和关注方向。不会自动写入聊天内容或 Book 正文。</p><label for="agent-memory">希望 Agent 长期记住的偏好</label><el-input id="agent-memory" v-model="memory" type="textarea" :rows="5" maxlength="4000" show-word-limit placeholder="例如：优先用中文解释，给初学者提供短代码示例，指出不确定之处。"/><el-button type="primary" native-type="submit" :loading="memoryBusy">保存 Agent 偏好</el-button></form><div class="knowledge-panel"><h2>完整备份</h2><p>下载你拥有的 Book、历史修订、分类标签、采集来源与原文件。分享给你的内容由其所有者备份。</p><p class="muted">备份不含登录凭据或模型密钥。单次最多 500 本、256MB 展开内容、100MB 压缩包；恢复后默认私有草稿。</p><div class="row-actions"><el-button type="primary" :loading="busy" @click="backup">下载完整备份</el-button><el-button :disabled="busy" @click="upload.click()">从备份恢复</el-button><input ref="upload" type="file" accept=".zip" hidden @change="restore"/></div><div v-if="result" class="restore-result" role="status"><h3>已恢复 {{result.bookIds.length}} 本 Book</h3><RouterLink v-for="id in result.bookIds" :key="id" :to="`/books/${id}`">Book #{{id}}　</RouterLink></div></div></div></section></template>
